// === Tab: mySketch.js ===
//for the #wccChallenge on the theme of 'Chemistry'. Decided to rework an on-theme sketch of mine from a year ago.
//On the WccChallenge stream last week Raph had pointed out a fullscreen() toggle function in my sketch and credited it to me, 
//even though I said I'm sure I stole it.(Definitely I did)
//So along w reworking it,  I started heavily annotating this old sketch, crediting my inspirations
//and it became a WHOLE THING, 
// entirely too long, where I detail all it's influences and open thievery.
// It's a bit embarassing , but as I've already written it, I'm going to let it go.
//So, read on through or skip around, or skip it entirely. There's lots of admissions of guilt
//and maybe a few useful nuggets in here.
//Also, I really do know how to write my own code now. 🤞



let avoiders=[]
let colors= ["#721121","#a5402d","#f15156","#ffc07f","#ffcf99"]
//👆Totally, 100% an exported palette from coolors.co . I care not what anyone thinks.
//I mean I'm sure I hit that space bar 50-60 times until I came on the right one
//that is already more work then 90% of the AI art I see on Twitter 🤭🤨

var cnv;

// 👇ooo, whats this? a nice JS function to center the canvas? nice work Google!
//OP will do this for you, but will also change bg color of page to match bg of sketch.
// In this case I want it to match the mask, so 
//I set the BG color of page in the style.css
function centerCanvas() {
  var x = (windowWidth - width) / 2;
  var y = (windowHeight - height) / 2;
  cnv.position(x, y);
}

function setup() {
  cnv= createCanvas(600, 600);
	 b= createGraphics(700, 700);
	centerCanvas();
  angleMode(DEGREES)
	//degrees, because when I first wrote this, I did not understand radians.
  for(let i=0; i<40; i++){
    avoiders.push(new avoider())
  }

	//ok, this texture algorithm 👇 I definitely stole . 98% sure it was from **Che-Yu Wu (https://openprocessing.org/user/139364)**
	//an amazingly talented artist, who also adds lots of in-progress stuff to openProcessing- nice to learn from
	//(not that I learned from this at the time I made this, so much as I copied and pasted it)
	//creates a nice papery texture by applying noise to the pixel array, that is blended with the rest of the 'art' later on.

  Texture=createGraphics(width,height)
	Texture.loadPixels()
	for(var i=0;i<width+50;i++){
		for(var o=0;o<height+50;o++){
			Texture.set(i,o,color(150,noise(i/10,o/10)*random([0,0,0,50,100])))
}
    }
  Texture.updatePixels()
    }

function draw() {
  clear()
	//clear() is your friend if you are going to abuse blendMode() as much as I'm about to
  background(255, 240, 235);
	//-------look👆! I DO know how to make my own colors
	push()
		blendMode(MULTIPLY)
		image(Texture,0,0)
	//blending the texture
	pop()

  for(let avoider of avoiders){
    avoider.update()
    avoider.relate()
    avoider.display()
  }	
	//now 'b' below is a mask (why did I name it b? no idea. I should have called it 'mask'. Clearly written code is easier to fix)
	//I 'borrowed' this idea of a round mask blended with the background from Roni-- **Roni Kaufman (https://openprocessing.org/user/184331)**
	//An elegant code artist who you all probably know, seriously, you all know who Roni is.
	//Now, the white glow using a drop shadow w drawingContext? 
	//I stole THAT from **Takawo**- I'm not going to even link him, if you don't know his work,
	//I'm not sure how you got here, google it.
	//NOW, using white glow ON a masking layer to soften the edges?? 
	//that was *me*. I came up with that on my own 🥹
  b.background(255)
  b.erase();
  b.ellipse(b.width/2, b.height/2, 600, 600);
  b.noErase();
  blendMode(SCREEN)
  drawingContext.shadowBlur = 75;
  drawingContext.shadowColor = 'white';
  image(b, -45, -45, 690, 690)
  drawingContext.shadowBlur= 0
  blendMode(MULTIPLY)
}

//This whole particle class bit I learned (like over half of creative coders I'm guessing) from **Daniel Shiffman of the Coding Train**. 
//I mean I tweaked it, and I think I wrote the 'relate' function by myself, but it's still mostly Shiffman's code
//but that's NOT thieving, as they are TUTORIALS. 🧐 🫡 🚂
class avoider{
  constructor(){
		//oooo... VECTORS! I actually use them in almost every sketch I write now,
		//if for no other reason than for a convenient place to hold both the x and y of a point, but the vector math functions
		//are super useful for all sorts of things and p5.Vector.lerp may be my favorite function in all p5
    this.pos= createVector(random(0, width), random(0, height))
    this.vel= createVector(0, 0)
    this.acc= p5.Vector.random2D();
    this.color=color (random(colors))
  }

  update(){
    this.acc.setMag(0.01)
    this.vel.add(this.acc)
    this.pos.add(this.vel)
    this.vel.limit(1)

    //edges-- can't have those pesky particles keep floating off-screen (PERFORMANCE!), delete or wrap them, wrapped in this case
    if(this.pos.x<-10){
      this.pos.x=width+10
    }
    if(this.pos.x>width+10){
      this.pos.x=-10
    }
    if(this.pos.y<-10){
      this.pos.y=height+10
    }
    if(this.pos.y>height+10){
      this.pos.y=-10
    }

  }
  //all by myself...🥹
	//particles give each other a little yank as they pass by
	//get your mind out of the gutter.
  relate(){
    for(let j=0; j<avoiders.length; j++){
      let distance = p5.Vector.dist(this.pos, avoiders[j].pos)
      if(distance < 50){
         this.pos.rotate(0.3)
        stroke(this.color)

		//wait, I did steal this idea 👇of drawing lines between close particles
		//right from the p5 examples in the documentation--- https://p5js.org/examples/simulate-particles.html
        line(this.pos.x, this.pos.y, avoiders[j].pos.x, avoiders[j].pos.y)
         }
    }

  }

  display(){

    noStroke()
		//👇more drawingContext shenanigans, probably originally learned from reading Takawo's code, though I
		//offset the positions of the two colors to produce a subtle shading on the 'atoms'
		let coloring= drawingContext.createRadialGradient(this.pos.x-10, this.pos.y, 75, this.pos.x+10, this.pos.y, 1)
	  coloring.addColorStop(0, 'black')
		coloring.addColorStop(1, this.color)
		drawingContext.fillStyle= coloring
    ellipse(this.pos.x, this.pos.y, 25)

  }
}

function windowResized() {
  centerCanvas();
}
//FINALLY, the function that Raph noticed on stream and tried to give me credit for. I remembered where I got it from--
//***the P5 reference page for fullscreen()!!!!!***--- https://p5js.org/reference/#/p5/fullscreen
//This sketch does look quite nice fullscreen I think, so click away!
function mousePressed() {
    let fs = fullscreen();
    fullscreen(!fs);
  }

